#include <bits/stdc++.h>
using namespace std;
int main(){
    int T; cin >> T;
    for (int t=0;t<T;t++){
        long long k; cin >> k;
        long long ak = llabs(k);
        long long n=1, s=1;
        while (!(s>=ak && (s-ak)%2==0)) { n++; s+=n; }
        if (t) cout << "\n";
        cout << n << "\n";
    }
}

